def cantor_numbering(N: int) -> str:
    if N == 0:
        return '1/1'
    else:
        n = N
        while n % 2 == 0:
            n //= 2
        k = 0
        while n > 1:
            if n % 2 == 0:
                k += 1
            n //= 2
        return str(2 * n + 1) + ' / ' + str(k + 1)
