def verify_isbn(isbn: str) -> str:
    isbn = isbn.replace('-', '')

    # Check if the ISBN is 10 digits or 13 digits long
    if len(isbn) not in [10, 13]:
        return "Error: Invalid format"

    # Calculate the checksum for a 10-digit ISBN
    if len(isbn) == 10:
        if not isbn[:-1].isdigit() or not isbn[-1:].isalpha():
            return "Error: Invalid format"
        digit_values = [int(digit) for digit in isbn[:-1]]
        weight_values = [1, 3, 1, 3, 1, 3, 1, 3, 1, 5]
        checksum_sum = sum(digit_values[i] * weight_values[i] for i in range(10))
        expected_checksum = (11 - checksum_sum % 11) % 11
        if expected_checksum == 10 and isbn[-1] == 'X':
            return "Right"
        elif expected_checksum == 10 and isbn[-1] == 'x':
            return "Right"
        elif expected_checksum == int(isbn[-1]):
            return "Right"
        else:
            return isbn + '-' + str(expected_checksum)

    # Calculate the checksum for a 13-digit ISBN
    if len(isbn) == 13:
        if not isbn.isdigit():
            return "Error: Invalid format"
        checksum_sum = sum(int(digit) * (1 if i % 2 == 0 else 3) for i, digit in enumerate(isbn))
        expected_checksum = 10 - (checksum_sum % 10)
        if expected_checksum == int(isbn[-1]):
            return "Right"
        else:
            return isbn + '-' + str(expected_checksum)

    return "Error: Invalid format"
