def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Create a 2D array to store the maximum importance values for each item and budget
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the dp array using the bottom-up approach
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        for j in range(1, n + 1):
            if price <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum happiness is stored in the bottom-right corner of the dp array
    return dp[m][n]
```

