    dp = [[0 for i in range(N)] for j in range(N)]

    for l in range(N+1):
        for i in range(N-l):
            j = i + l - 1

            if l == 1:
                dp[i][j] = beads[i]
            else:
                max_energy = 0
                for k in range(i, j):
                    max_energy = max(max_energy, dp[i][k] * beads[k] * beads[j])
                dp[i][j] = max_energy

    return dp[0][N-1]
