def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original) or len(encoded) < len(message) + 1:
        return "Failed"

    mapping = {}
    for i in range(len(original)):
        char_e = encoded[i]
        char_o = original[i]

        if char_o not in mapping:
            mapping[char_o] = char_e
        elif mapping[char_o] != char_e:
            return "Failed"

    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded
