def count_coprime_pairs(x0, y0):
    result = 0
    quotient = y0 // x0

    # Iterate through all possible factors 'a' of the quotient
    for a in range(1, quotient + 1):
        # Calculate the corresponding factor 'b' such that 'a * b = y0 / x0'
        b = quotient // a

        # Check if 'a' and 'b' are co-prime (their GCD is 1)
        if gcd(a, b) == 1:
            result += 1

            # If 'a' and 'b' are not the same, increment the count by 2 to account for both (P, Q) and (Q, P) pairs
            if a != b:
                result += 1

    return result

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x
