def is_prime(num: int) -> bool:
    # Edge cases
    if num <= 1:
        return False
    if num <= 3:
        return True

    # Check divisibility by 2 and 3
    if num % 2 == 0 or num % 3 == 0:
        return False

    # Only check up to the square root of the number
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
