def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a 2D list to store the maximum value that can be picked with a given time
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for t in range(1, T + 1):
            if t >= time:
                dp[i][t] = max(dp[i - 1][t], dp[i - 1][t - time] + value)
            else:
                dp[i][t] = dp[i - 1][t]

    # Find the maximum value that can be picked with the given time limit
    return dp[M][T]
