def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a table 'dp' with n+1 rows and V+1 cols to store the maximum volume that can be occupied
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Iterate through each item and each possible volume from 1 to V
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            # Include the current item in the maximum volume if the current volume is sufficient
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    min_remaining_space = V - dp[n][V]

    return min_remaining_space
