def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    comb = [0] * (m+1)
    comb[0] = comb[1] = 1
    for i in range(2, m+1):
        comb[i] = (comb[i-1] + comb[i-2]) % MOD
    ans = 1
    for i in range(n):
        if a[i] > m:
            return 0
        ans = (ans * comb[m] % MOD) * inv(comb[a[i]], MOD)
    return ans

def inv(x, MOD):
    return pow(x, MOD-2, MOD)  # Using Fermat's Little Theorem
