def find_most_unhappy_day(schedule) -> int:
    total_hours = sum(pair for pair in schedule)
    threshold = 8
    max_unhappiness = 0
    most_unhappy_day = 0

    for day, (school_hours, extra_hours) in enumerate(schedule):
        current_unhappiness = school_hours + extra_hours
        if current_unhappiness > total_hours - threshold:
            if current_unhappiness > max_unhappiness:
                max_unhappiness = current_unhappiness
                most_unhappy_day = day
        elif current_unhappiness == max_unhappiness:
            most_unhappy_day = min(most_unhappy_day, day)

    return most_unhappy_day + 1 if most_unhappy_day != 0 else 0
