def min_groups(w, n, prices):
    # Initialize the DP table with infinity
    dp = [[float('inf')] * (n+1) for _ in range(w+1)]

    # Base case: 0 souvenirs required for a group where sum price is 0
    for i in range(1, w+1):
        dp[i][0] = 0

    for i in range(1, w+1):
        for j in range(1, n+1):
            # If the souvenir can fit in the current group price
            if prices[j-1] <= i:
                # Include the current souvenir in the group or exclude it
                dp[i][j] = min(dp[i][j], 1 + dp[i-prices[j-1]][j-1] if j > 0 else dp[i][j-1])
            else:
                # Exclude the current souvenir
                dp[i][j] = dp[i][j-1]

    return dp[w][n]
```
